import { Component, createSignal, onCleanup, onMount } from "solid-js";

import { InterfaceMode } from "#core/ui/interface-modes/interface-modes.js";
import { Panel } from "#core/ui-next/components/panel.jsx";
import { Popup, PopupContextProvider } from "#core/ui-next/components/popup.jsx";
import { ScreenFlowContextProvider, ScreenFlowScreen, ScreenFlowTab } from "#core/ui-next/components/screen-flow.jsx";
import { Tab } from "#core/ui-next/components/tab.jsx";
import { NestedTooltipContext } from "#core/ui-next/components/tooltip-compat.jsx";
import { AgeSelectModel, AgeSelectModelContext } from "#core/ui-next/screens/create-game/age-select-model.js";
import { CivDetails } from "#core/ui-next/screens/create-game/civ-details.jsx";
import { CivInfo, CivSelectModel, CivSelectModelContext } from "#core/ui-next/screens/create-game/civ-select-model.js";
import { CivSelectScreen } from "#core/ui-next/screens/create-game/civ-select-screen.jsx";
import { GameSetupModel, GameSetupModelContext } from "#core/ui-next/screens/create-game/create-game-setup-model.js";
import { LeaderSelectModel, LeaderSelectModelContext } from "#core/ui-next/screens/create-game/leader-select-model.js";
import {
	MementoSelectModel,
	MementoSelectModelContext,
} from "#core/ui-next/screens/create-game/memento-select-model.js";
import { MementoSelect } from "#core/ui-next/screens/create-game/memento-select.jsx";
import {
	RecommendedChoiceModel,
	RecommendedChoiceModelContext,
} from "#core/ui-next/screens/create-game/recommended-choice-model.js";
import { TotModel, TotModelContext } from "#core/ui-next/screens/create-game/tot-model.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import { AgeTransitionCivChoiceScreen } from "#base/ui-next/screens/age-transition/civ-choice-screen.jsx";

export interface AgeTransitionScreenProps {
	screens: ScreenFlowScreen[];
}

const ageTransitionStatic = {
	lastScreen: undefined as string | undefined,
	viewCiv: undefined as CivInfo | undefined,
};

export const AgeTransitionScreenComponent: Component<AgeTransitionScreenProps> = (props) => {
	const ageSelectModel = AgeSelectModel.get();
	const civSelectModel = CivSelectModel.get();
	const leaderSelectModel = LeaderSelectModel.get();
	const gameSetupModel = GameSetupModel.get();
	const totModel = TotModel.get();
	const mementoModel = MementoSelectModel.get();
	const choiceModel = RecommendedChoiceModel.get();
	const audioTrigger = useAudio("AgeTransitionPopup");

	const [popupContext, setPopupContext] = createSignal<PopupContextProvider>();
	let flowContextRef!: ScreenFlowContextProvider;

	function closeScreen(screen?: string) {
		ageTransitionStatic.lastScreen = screen;
		ageTransitionStatic.viewCiv = civSelectModel.viewCiv();
		InterfaceMode.switchToDefault();
	}

	function handleCancelInput() {
		if (popupContext()?.active()) {
			popupContext()?.close();
		} else {
			flowContextRef?.activatePrev();
		}
	}

	function doCompleteChoices(screen: string) {
		// Send the updated choices.
		sendFinishedMakingAgeTransitionChoices();
		// Close the screen.  The player can come back later if they want to change them.
		closeScreen(screen);
	}

	function sendFinishedMakingAgeTransitionChoices() {
		const args = {
			Finished: true,
		};

		const result = Game.PlayerOperations.canStart(
			GameContext.localPlayerID,
			PlayerOperationTypes.SET_AGE_TRANSITION_DATA,
			args,
			false,
		);

		if (result.Success) {
			Game.PlayerOperations.sendRequest(
				GameContext.localPlayerID,
				PlayerOperationTypes.SET_AGE_TRANSITION_DATA,
				args,
			);
		}

		return result.Success;
	}

	onMount(() => {
		// If we were are loading to civ details we need to restore the view civ
		if (ageTransitionStatic.lastScreen == "civ-details") {
			civSelectModel.setViewCiv(ageTransitionStatic.viewCiv);
		}
		audioTrigger("popup-open");
	});

	onCleanup(() => {
		audioTrigger("popup-close");
	});

	return (
		<Panel
			id="age-transition-screen"
			name="age-transition-screen"
			class="fullscreen"
			onCancelInput={() => {
				handleCancelInput();
			}}
		>
			<GameSetupModelContext.Provider value={gameSetupModel}>
				<AgeSelectModelContext.Provider value={ageSelectModel}>
					<CivSelectModelContext.Provider value={civSelectModel}>
						<LeaderSelectModelContext.Provider value={leaderSelectModel}>
							<TotModelContext.Provider value={totModel}>
								<MementoSelectModelContext.Provider value={mementoModel}>
									<NestedTooltipContext.Provider value={{ disabled: true }}>
									<RecommendedChoiceModelContext.Provider value={choiceModel}>
										<Popup setPopupContext={setPopupContext}>
											<ScreenFlowTab
												class="fullscreen"
												defaultTab={ageTransitionStatic.lastScreen ?? props.screens[0].name}
												screens={props.screens}
												onClose={(screen) => closeScreen(screen)}
												onStart={(screen) => doCompleteChoices(screen)}
												contextRef={(ref) => {
													flowContextRef = ref;
												}}
											>
												<Tab.Output />
												<Tab.Item
													name="civ-choice"
													title={() => null}
													body={() => <AgeTransitionCivChoiceScreen />}
												/>
												<Tab.Item
													name="civ-select"
													title={() => null}
													body={() => <CivSelectScreen />}
												/>
												<Tab.Item
													name="civ-details"
													title={() => null}
													body={() => <CivDetails />}
												/>
												<Tab.Item
													name="memento-select"
													title={() => null}
													body={() => <MementoSelect />}
												/>
											</ScreenFlowTab>
											<Popup.Output class="fullscreen child-fullscreen" />
										</Popup>
									</RecommendedChoiceModelContext.Provider>
									</NestedTooltipContext.Provider>
								</MementoSelectModelContext.Provider>
							</TotModelContext.Provider>
						</LeaderSelectModelContext.Provider>
					</CivSelectModelContext.Provider>
				</AgeSelectModelContext.Provider>
			</GameSetupModelContext.Provider>
		</Panel>
	);
};

export const AgeTransitionScreen = ComponentRegistry.register({
	name: "AgeTransitionScreen",
	createInstance: AgeTransitionScreenComponent,
});

engine.whenReady.then(() => {
	engine.on("BeforeAgeTransition", () => {
		WorldUI.pushGaussianBlurFilter(5);
		engine.call("setSnapshotEnabled", true);
	});
	engine.on("LocalPlayerChanged", () => {
		// When the local player changes in Hotset, we must reset the state.
		ageTransitionStatic.lastScreen = undefined;
		ageTransitionStatic.viewCiv = undefined;
	});
});
